380 |     private static List<CorpusSearchHit> mergeHits(
381 |             List<CorpusSearchHit> primary, List<CorpusSearchHit> secondary) {
382 |         List<CorpusSearchHit> merged = new ArrayList<>(primary);
383 |         Set<String> seen = new HashSet<>();
384 |         for (CorpusSearchHit hit : primary) {
385 |             seen.add(normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl()));
386 |         }
387 |         for (CorpusSearchHit hit : secondary) {
388 |             String key = normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl());
389 |             if (seen.add(key)) merged.add(hit);
