415 |     private static List<CorpusSearchHit> filterByRequestedBook(
416 |             List<CorpusSearchHit> hits, List<String> requestedBookTokens) {
417 |         if (requestedBookTokens.isEmpty()) return hits;
418 |         int requiredMatches = requestedBookTokens.size() <= 2 ? requestedBookTokens.size() : 2;
419 |         return hits.stream()
420 |                 .filter(hit -> countBookTokenMatches(hit, requestedBookTokens) >= requiredMatches)
421 |                 .collect(Collectors.toList());
