424 |     private static int countBookTokenMatches(CorpusSearchHit hit, List<String> requestedBookTokens) {
425 |         String normalizedTitle = normalizeForMatch(hit.title());
426 |         String normalizedUrl   = normalizeForMatch(hit.sourceUrl());
427 |         int matches = 0;
428 |         for (String token : requestedBookTokens) {
429 |             if (normalizedTitle.contains(token) || normalizedUrl.contains(token)) matches++;
430 |         }
431 |         return matches;
432 |     }
