434 |     private static boolean containsAnyContentTerm(String quote, List<String> contentTerms) {
435 |         String normalizedQuote = normalizeForMatch(quote);
436 |         Set<String> quoteTokens = new HashSet<>();
437 |         for (String token : normalizedQuote.split("\\s+")) {
