202 |                         retrievalPoolSize, requiredAuthor, explicitTitle,
203 |                         List.of(), appConfig
204 |                     ).hits();
205 |                     logCount(appConfig, "semantic fallback conceptHits", conceptHits.size());
206 |                     if (!conceptHits.isEmpty()) {
207 |                         List<String> aiOnlyTerms = inferEffectiveConceptTerms("", requiredAuthor, intent.concepts());
208 |                         List<CorpusSearchHit> conceptFiltered = filterByRequestedAuthor(requiredAuthor, conceptHits);
209 |                         // Do NOT apply filterByContentTerms here — the concept FTS already ensures
210 |                         // topical relevance. Exact-token filtering causes false negatives when FTS
211 |                         // prefix (e.g. "love*") matched inflected forms ("beloved", "loveth") that
212 |                         // fail exact-word comparison. The Gemini reranker handles final selection.
213 |                         candidatePool = rankForDisplay(removeBoilerplateAndDuplicates(conceptFiltered), requiredAuthor);
214 |                         logCount(appConfig, "candidatePool (semantic fallback)", candidatePool.size());
215 |                         logIntentDebug(appConfig, topic,
216 |                             "SEMANTIC-FALLBACK:" + conceptOrFtsQuery, intent,
217 |                             requiredAuthor, List.of(), aiOnlyTerms);
218 |                     }
219 |                 }
220 |             }
221 | 
222 |             List<CorpusSearchHit> curated = pickFinalQuotesWithRerank(
223 |                 topic,
224 |                 candidatePool,
225 |                 requestedQuotes,
226 |                 geminiClient,
227 |                 appConfig
228 |             );
229 |             if (curated.isEmpty()) {
230 |                 return new ResearchReport(appConfig.noResultsText(), List.of());
231 |             }
232 | 
233 |             List<QuoteResult> quotes = curated.stream()
234 |                 .map(hit -> new QuoteResult(
235 |                     hit.quote(),
236 |                     blankToFallback(hit.author(), "Unknown"),
237 |                     blankToFallback(hit.title(), "Untitled"),
238 |                     blankToFallback(hit.locator(), "Not specified"),
239 |                     blankToFallback(hit.sourceUrl(), "N/A")
240 |                 ))
241 |                 .toList();
242 | 
243 |             String displayQuery = hitsResult.effectiveQuery()
244 |                 .replaceAll("NEAR\\(([^,]+),\\s*\\d+\\)", "$1")
245 |                 .replace("*", "")
246 |                 .replace(" AND ", " and ")
247 |                 .replace(" OR ", " or ");
248 |             String summary;
249 |             if (hitsResult.usedFallback()) {
250 |                 summary = "Local corpus returned " + quotes.size()
251 |                     + " passage(s) — exact search found nothing; broadened to: " + displayQuery
252 |                     + "  (Tip: try fewer, more specific keywords)"
253 |                     + "\n<ctrl-a> highlight quote <ctrl-c> copy quote (Right Mouse)";
254 |             } else {
255 |                 summary = "Local corpus returned " + quotes.size()
256 |                     + " passage(s) — searched: " + displayQuery
257 |                     + "\n<ctrl-a> highlight quote <ctrl-c> copy quote (Right Mouse also)";
258 |             }
259 |             return new ResearchReport(summary, quotes);
260 |         } catch (IllegalStateException exception) {
261 |             return new ResearchReport(appConfig.noResultsText(), List.of());
262 |         }
263 |     }
