283 |     private static List<CorpusSearchHit> pickFinalQuotesWithRerank(
284 |         String topic,
285 |         List<CorpusSearchHit> candidatePool,
286 |         int requestedQuotes,
287 |         GeminiClient geminiClient,
288 |         AppConfig appConfig
289 |     ) {
290 |         if (candidatePool.isEmpty()) {
291 |             return List.of();
292 |         }
293 | 
294 |         List<CorpusSearchHit> boundedPool = candidatePool.stream().limit(Math.max(20, requestedQuotes * 6)).toList();
295 |         List<Integer> selectedIds =
296 |             geminiClient.rerankLocalCandidates(topic, boundedPool, requestedQuotes, appConfig);
297 | 
298 |         if (selectedIds.isEmpty()) {
299 |             return boundedPool.stream().limit(requestedQuotes).toList();
300 |         }
301 | 
302 |         List<CorpusSearchHit> selected = new ArrayList<>();
303 |         for (Integer id : selectedIds) {
304 |             int index = id - 1;
305 |             if (index >= 0 && index < boundedPool.size()) {
306 |                 selected.add(boundedPool.get(index));
307 |             }
308 |         }
309 | 
310 |         if (selected.isEmpty()) {
311 |             return boundedPool.stream().limit(requestedQuotes).toList();
312 |         }
313 | 
314 |         if (selected.size() < requestedQuotes) {
315 |             Set<String> selectedKeys = new HashSet<>();
316 |             for (CorpusSearchHit hit : selected) {
317 |                 selectedKeys.add(normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl()));
318 |             }
319 | 
320 |             for (CorpusSearchHit hit : boundedPool) {
321 |                 if (selected.size() >= requestedQuotes) {
322 |                     break;
323 |                 }
324 |                 String key = normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl());
325 |                 if (selectedKeys.add(key)) {
326 |                     selected.add(hit);
327 |                 }
328 |             }
329 |         }
330 | 
331 |         return selected.stream().limit(requestedQuotes).toList();
332 |     }
