334 |     private static List<CorpusSearchHit> removeBoilerplateAndDuplicates(List<CorpusSearchHit> hits) {
335 |         List<CorpusSearchHit> curated = new ArrayList<>();
336 |         Set<String> seen = new HashSet<>();
337 |         for (CorpusSearchHit hit : hits) {
338 |             String reason = boilerplateReason(hit);
339 |             if (reason != null) {
340 |                 String snippet = normalizeForMatch(hit.quote());
341 |                 String display = snippet.length() > 120 ? snippet.substring(0, 120) + "..." : snippet;
342 |                 LOGGER.info(() -> "[BoilerplateFilter] removed (" + reason + "): \"" + display + "\"");
343 |                 continue;
344 |             }
345 | 
346 |             String key = normalizeForMatch(hit.quote());
347 |             if (key.isBlank() || !seen.add(key)) {
348 |                 continue;
349 |             }
350 |             curated.add(hit);
351 |         }
352 |         return curated;
353 |     }
