355 |     private static List<CorpusSearchHit> rankForDisplay(List<CorpusSearchHit> hits, String requiredAuthor) {
356 |         return hits.stream()
357 |             .sorted((left, right) -> {
358 |                 // Phrase hits (score <= -99990) always sort first — explicit LIKE matches.
359 |                 boolean leftIsPhrase  = left.score()  <= -99990;
360 |                 boolean rightIsPhrase = right.score() <= -99990;
361 |                 if (leftIsPhrase != rightIsPhrase) {
362 |                     return leftIsPhrase ? -1 : 1;
363 |                 }
364 |                 // Among multiple phrase hits, prefer shorter passages. A short passage where
365 |                 // the query covers most of the text is a more precise match than a long passage
366 |                 // that incidentally contains the query words in sequence.
367 |                 if (leftIsPhrase) {
368 |                     int leftLen  = left.quote()  == null ? 0 : left.quote().length();
369 |                     int rightLen = right.quote() == null ? 0 : right.quote().length();
370 |                     return Integer.compare(leftLen, rightLen);
371 |                 }
372 | 
373 |                 int leftSourcePriority = sourcePriority(left, requiredAuthor);
374 |                 int rightSourcePriority = sourcePriority(right, requiredAuthor);
375 |                 if (leftSourcePriority != rightSourcePriority) {
376 |                     return Integer.compare(leftSourcePriority, rightSourcePriority);
377 |                 }
378 | 
379 |                 int leftBand = qualityBand(left.quote());
380 |                 int rightBand = qualityBand(right.quote());
381 |                 if (leftBand != rightBand) {
382 |                     return Integer.compare(leftBand, rightBand);
383 |                 }
384 |                 return Double.compare(left.score(), right.score());
385 |             })
386 |             .toList();
387 |     }
388 | 
389 |     private static int sourcePriority(CorpusSearchHit hit, String requiredAuthor) {
390 |         String normalizedAuthor = normalizeForMatch(requiredAuthor);
391 |         String normalizedTitle = normalizeForMatch(hit.title());
392 |         String normalizedUrl = normalizeForMatch(hit.sourceUrl());
393 | 
394 |         if (!"universal house of justice".equals(normalizedAuthor)) {
395 |             return 1;
396 |         }
397 | 
398 |         if (normalizedUrl.contains("the universal house of justice messages")
399 |             || normalizedUrl.contains("the universal house of justice muhj")
400 |             || normalizedTitle.contains("messages from the universal house of justice")) {
401 |             return 0;
402 |         }
403 | 
404 |         if (normalizedUrl.contains("authoritative texts compilations")
405 |             || normalizedUrl.contains("other literature")
406 |             || normalizedUrl.contains("official statements commentaries")) {
407 |             return 3;
408 |         }
409 | 
410 |         return 1;
411 |     }
412 | 
413 |     private static int qualityBand(String quote) {
414 |         int length = quote == null ? 0 : quote.trim().length();
415 |         if (length >= 200 && length <= 900) {
416 |             return 0;
417 |         }
418 |         if (length >= 120 && length <= 1100) {
419 |             return 1;
420 |         }
421 |         return 2;
422 |     }
