424 |     /** Returns a short label identifying which boilerplate check matched, or null if not boilerplate. */
425 |     private static String boilerplateReason(CorpusSearchHit hit) {
426 |         // A passage over 15,000 characters is an entire book ingested as one chunk — not a usable quote.
427 |         // Individual prayers, tablets, and letters are well under this limit even when lengthy.
428 |         if (hit.quote().length() > 15_000) {
429 |             return "too-long";
430 |         }
431 |         String quote = normalizeForMatch(hit.quote());
432 |         if (quote.contains("bahai reference library")) {
433 |             return "bahai-ref-lib";
434 |         }
435 |         if (quote.startsWith("a collection of") || quote.startsWith("a selection of")) {
436 |             return "collection-header";
437 |         }
438 |         if (quote.contains("can be found here")) {
439 |             return "found-here";
440 |         }
441 |         if (quote.contains("downloads about downloads")
442 |             || quote.contains("all downloads in authoritative writings and guidance")
443 |             || quote.contains("copyright and terms of use")
444 |             || quote.contains("read online")
445 |             || quote.contains("bahai org home")
446 |             || quote.contains("search the bahai reference library")) {
447 |             return "nav-element";
448 |         }
449 |         if (quote.contains("see also")) {
450 |             return "see-also";
451 |         }
452 |         return null;
453 |     }
