459 |     private static String buildHitsSql(boolean authorScoped, boolean titleScoped) {
460 |         String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
461 |         String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
462 |         return """
463 |             SELECT
464 |                 p.text_content,
465 |                 d.author,
466 |                 d.title,
467 |                 p.locator,
468 |                 d.canonical_url,
469 |                 bm25(passages_fts) AS score
470 |             FROM passages_fts
471 |             JOIN passages p ON p.passage_id = passages_fts.rowid
472 |             JOIN documents d ON d.doc_id = p.doc_id
473 |             WHERE passages_fts MATCH ?
474 |             """ + authorClause + titleClause + """
475 |             ORDER BY score
476 |             LIMIT ?
477 |             """;
478 |     }
479 | 
480 |     private static String buildPhraseSql(boolean authorScoped, boolean titleScoped) {
481 |         String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
482 |         String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
483 |         return """
484 |             SELECT
485 |                 p.text_content,
486 |                 d.author,
487 |                 d.title,
488 |                 p.locator,
489 |                 d.canonical_url,
490 |                 -99999.0 AS score
491 |             FROM passages p
492 |             JOIN documents d ON d.doc_id = p.doc_id
493 |             WHERE lower(p.text_content) LIKE ?
494 |             """ + authorClause + titleClause + """
495 |             LIMIT ?
496 |             """;
497 |     }
498 | 
499 |     private static String buildBookScopedSql(boolean authorScoped, boolean titleScoped) {
500 |         String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
501 |         String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
502 |         return "SELECT\n"
503 |             + "    p.text_content,\n"
504 |             + "    d.author,\n"
505 |             + "    d.title,\n"
506 |             + "    p.locator,\n"
507 |             + "    d.canonical_url,\n"
508 |             + "    -99998.0 AS score\n"
509 |             + "FROM passages p\n"
510 |             + "JOIN documents d ON d.doc_id = p.doc_id\n"
511 |             + "WHERE 1=1\n"
512 |             + authorClause + titleClause
513 |             + "LIMIT ?\n";
514 |     }
