516 |     // -------------------------------------------------------------------------
517 |     // Core search — findHits with NEAR/AND/OR fallback
518 |     // -------------------------------------------------------------------------
519 | 
520 |     private static HitsResult findHits(
521 |         CorpusPaths corpusPaths,
522 |         String nearQuery,
523 |         String ftsQuery,
524 |         String orFtsQuery,
525 |         int limit,
526 |         String requiredAuthor,
527 |         String explicitTitle,
528 |         List<String> requestedBookTokens,
529 |         AppConfig appConfig
530 |     ) {
531 |         boolean authorScoped = requiredAuthor != null && !requiredAuthor.isBlank();
532 |         boolean titleScoped  = explicitTitle  != null && !explicitTitle.isBlank();
533 |         String sql = buildHitsSql(authorScoped, titleScoped);
534 | 
535 |         SQLException lastException = null;
536 |         for (int attempt = 1; attempt <= 3; attempt++) {
537 |             List<CorpusSearchHit> hits = new ArrayList<>();
538 |             try (Connection connection = CorpusConnectionFactory.open(corpusPaths)) {
539 |                 // Try NEAR first (exactly-2-token queries only), then AND, then OR fallback
540 |                 String effectiveQuery = ftsQuery;
541 |                 boolean usedOrFallback = false;
542 | 
543 |                 if (nearQuery != null && !nearQuery.isBlank()) {
544 |                     logCount(appConfig, "FtsQuery NEAR: " + nearQuery + " →", 0);
545 |                     hits = executeHitsQuery(connection, sql, nearQuery,
546 |                         authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
547 |                     logCount(appConfig, "FtsQuery NEAR hits", hits.size());
548 |                     if (!hits.isEmpty()) effectiveQuery = nearQuery;
549 |                 }
550 | 
551 |                 if (hits.isEmpty()) {
552 |                     logCount(appConfig, "FtsQuery AND: " + ftsQuery + " →", 0);
553 |                     hits = executeHitsQuery(connection, sql, ftsQuery,
554 |                         authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
555 |                     logCount(appConfig, "FtsQuery AND hits", hits.size());
556 |                 }
557 | 
558 |                 if (hits.isEmpty() && !orFtsQuery.isBlank() && !orFtsQuery.equals(ftsQuery)) {
559 |                     logCount(appConfig, "FtsQuery AND=0, OR: " + orFtsQuery + " →", 0);
560 |                     hits = executeHitsQuery(connection, sql, orFtsQuery,
561 |                         authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
562 |                     logCount(appConfig, "FtsQuery OR hits", hits.size());
563 |                     usedOrFallback = true;
564 |                     effectiveQuery = orFtsQuery;
565 |                 }
566 | 
567 |                 if (!requestedBookTokens.isEmpty()) {
568 |                     hits = filterByRequestedBook(hits, requestedBookTokens);
569 |                 }
570 | 
571 |                 return new HitsResult(hits.stream().limit(Math.max(1, limit)).toList(),
572 |                     effectiveQuery, usedOrFallback);
573 |             } catch (SQLException exception) {
574 |                 lastException = exception;
575 |                 if (!isBusyLock(exception) || attempt == 3) {
576 |                     break;
577 |                 }
578 | 
579 |                 try {
580 |                     Thread.sleep(200L * attempt);
581 |                 } catch (InterruptedException interruptedException) {
582 |                     Thread.currentThread().interrupt();
583 |                     throw new IllegalStateException("Local corpus query was interrupted.", interruptedException);
584 |                 }
585 |             }
586 |         }
587 | 
588 |         throw new IllegalStateException("Local corpus query failed.", lastException);
589 |     }
