591 |     private static List<CorpusSearchHit> executeHitsQuery(
592 |         Connection connection,
593 |         String sql,
594 |         String ftsQuery,
595 |         boolean authorScoped,
596 |         String requiredAuthor,
597 |         boolean titleScoped,
598 |         String explicitTitle,
599 |         int limit
600 |     ) throws SQLException {
601 |         List<CorpusSearchHit> hits = new ArrayList<>();
602 |         try (PreparedStatement statement = connection.prepareStatement(sql)) {
603 |             int p = 1;
604 |             statement.setString(p++, ftsQuery);
605 |             if (authorScoped) {
606 |                 statement.setString(p++, requiredAuthor);
607 |             }
608 |             if (titleScoped) {
609 |                 statement.setString(p++, explicitTitle);
610 |             }
611 |             statement.setInt(p, Math.max(1, limit));
612 | 
613 |             try (ResultSet resultSet = statement.executeQuery()) {
614 |                 while (resultSet.next()) {
615 |                     hits.add(new CorpusSearchHit(
616 |                         trimToEmpty(resultSet.getString(1)),
617 |                         trimToEmpty(resultSet.getString(2)),
618 |                         trimToEmpty(resultSet.getString(3)),
619 |                         trimToEmpty(resultSet.getString(4)),
620 |                         trimToEmpty(resultSet.getString(5)),
621 |                         resultSet.getDouble(6)
622 |                     ));
623 |                 }
624 |             }
625 |         }
626 |         return hits;
627 |     }
