741 |     private static List<CorpusSearchHit> mergeHits(List<CorpusSearchHit> primary, List<CorpusSearchHit> secondary) {
742 |         List<CorpusSearchHit> merged = new ArrayList<>(primary);
743 |         Set<String> seen = new HashSet<>();
744 |         for (CorpusSearchHit hit : primary) {
745 |             seen.add(normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl()));
746 |         }
747 | 
748 |         for (CorpusSearchHit hit : secondary) {
749 |             String key = normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl());
750 |             if (seen.add(key)) {
751 |                 merged.add(hit);
752 |             }
753 |         }
754 |         return merged;
755 |     }
