766 |     private static List<CorpusSearchHit> filterByRequestedAuthor(String requiredAuthor, List<CorpusSearchHit> hits) {
767 |         if (requiredAuthor == null || requiredAuthor.isBlank()) {
768 |             return hits;
769 |         }
770 |         String normalizedRequired = normalizeForMatch(requiredAuthor);
771 |         return hits.stream()
772 |             .filter(hit -> normalizeForMatch(hit.author()).equals(normalizedRequired))
773 |             .toList();
