776 |     private static List<CorpusSearchHit> filterByContentTerms(List<CorpusSearchHit> hits, List<String> contentTerms) {
777 |         if (contentTerms.isEmpty()) {
778 |             return hits;
779 |         }
780 |         return hits.stream()
781 |             .filter(hit -> containsAnyContentTerm(hit.quote(), contentTerms))
782 |             .toList();
783 |     }
