785 |     private static List<CorpusSearchHit> filterByRequestedBook(List<CorpusSearchHit> hits, List<String> requestedBookTokens) {
786 |         if (requestedBookTokens.isEmpty()) {
787 |             return hits;
788 |         }
789 | 
790 |         int requiredMatches = requestedBookTokens.size() <= 2 ? requestedBookTokens.size() : 2;
791 |         return hits.stream()
792 |             .filter(hit -> countBookTokenMatches(hit, requestedBookTokens) >= requiredMatches)
793 |             .toList();
794 |     }
795 | 
796 |     private static int countBookTokenMatches(CorpusSearchHit hit, List<String> requestedBookTokens) {
797 |         String normalizedTitle = normalizeForMatch(hit.title());
798 |         String normalizedUrl = normalizeForMatch(hit.sourceUrl());
799 |         int matches = 0;
800 |         for (String token : requestedBookTokens) {
801 |             if (normalizedTitle.contains(token) || normalizedUrl.contains(token)) {
802 |                 matches++;
803 |             }
804 |         }
805 |         return matches;
806 |     }
807 | 
808 |     private static boolean containsAnyContentTerm(String quote, List<String> contentTerms) {
