        List<String> tokens = extractFtsTokens(topic, resolvedAuthor);
        if (tokens.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tokens.size(); i++) {
            if (i > 0) sb.append(" OR ");
            sb.append(tokens.get(i));
        }
