        for (int i = 0; i < required.size(); i++) {
            if (i > 0) sb.append(" AND ");
            sb.append(required.get(i));
        }
        sb.append(" AND (");
        for (int i = 0; i < optional.size(); i++) {
            if (i > 0) sb.append(" OR ");
            sb.append(optional.get(i));
