        if (isEmpty(resolvedAuthor)) return Collections.emptySet();
        Set<String> tokens = new HashSet<>();
        for (String token : normalizeForMatch(resolvedAuthor).split("\\s+")) {
            if (!token.isEmpty()) tokens.add(token);
