        }
        List<String> terms = new ArrayList<>();
        for (String token : normalizedTopic.split("\\s+")) {
            if (token.length() < 3) continue;
            if (NOISE_TOKENS.contains(token) || GENERIC_QUERY_TOKENS.contains(token)
