201 |                 // Use the OR concept query directly — semantic fallback is last-resort mode.
202 |                 // AND concept queries (e.g. "love* AND empathy* AND unity*") find only 1-2 narrow
203 |                 // passages and miss the OR fallback inside findHits because hits.isEmpty() is false.
204 |                 // Those 1-2 passages are often boilerplate-filtered, leaving candidatePool empty.
205 |                 // Going straight to OR ("love* OR unity* OR compassion*") retrieves a broad pool
206 |                 // of the most BM25-relevant passages on these themes across the full corpus,
207 |                 // with room for the Gemini reranker to pick the best for the specific question.
208 |                 if (!conceptOrFtsQuery.isBlank() && !conceptOrFtsQuery.equals(orFtsQuery)) {
209 |                     List<CorpusSearchHit> conceptHits = findHits(
210 |                         corpusPaths, "", conceptOrFtsQuery, conceptOrFtsQuery,
211 |                         retrievalPoolSize, requiredAuthor, explicitTitle,
212 |                         List.of(), appConfig
213 |                     ).hits();
214 |                     logCount(appConfig, "semantic fallback conceptHits", conceptHits.size());
215 |                     if (!conceptHits.isEmpty()) {
216 |                         List<String> aiOnlyTerms = inferEffectiveConceptTerms("", requiredAuthor, intent.concepts());
217 |                         List<CorpusSearchHit> conceptFiltered = filterByRequestedAuthor(requiredAuthor, conceptHits);
218 |                         // Do NOT apply filterByContentTerms here — the concept FTS already ensures
219 |                         // topical relevance. Exact-token filtering causes false negatives when FTS
220 |                         // prefix (e.g. "love*") matched inflected forms ("beloved", "loveth") that
221 |                         // fail exact-word comparison. The Gemini reranker handles final selection.
222 |                         candidatePool = rankForDisplay(removeBoilerplateAndDuplicates(conceptFiltered), requiredAuthor);
223 |                         logCount(appConfig, "candidatePool (semantic fallback)", candidatePool.size());
224 |                         logIntentDebug(appConfig, topic,
225 |                             "SEMANTIC-FALLBACK:" + conceptOrFtsQuery, intent,
226 |                             requiredAuthor, List.of(), aiOnlyTerms);
227 |                     }
228 |                 }
229 |             }
230 | 
231 |             List<CorpusSearchHit> curated = pickFinalQuotesWithRerank(
232 |                 topic,
233 |                 candidatePool,
234 |                 requestedQuotes,
235 |                 geminiClient,
236 |                 appConfig
237 |             );
238 |             if (curated.isEmpty()) {
239 |                 return new ResearchReport(appConfig.noResultsText(), List.of());
240 |             }
241 | 
242 |             List<QuoteResult> quotes = curated.stream()
243 |                 .map(hit -> new QuoteResult(
244 |                     hit.quote(),
245 |                     blankToFallback(hit.author(), "Unknown"),
246 |                     blankToFallback(hit.title(), "Untitled"),
247 |                     blankToFallback(hit.locator(), "Not specified"),
248 |                     blankToFallback(hit.sourceUrl(), "N/A")
249 |                 ))
250 |                 .toList();
251 | 
252 |             String displayQuery = hitsResult.effectiveQuery()
253 |                 .replaceAll("NEAR\\(([^,]+),\\s*\\d+\\)", "$1")
254 |                 .replace("*", "")
255 |                 .replace(" AND ", " and ")
256 |                 .replace(" OR ", " or ");
257 |             String summary;
258 |             if (hitsResult.usedFallback()) {
259 |                 summary = "Local corpus returned " + quotes.size()
260 |                     + " passage(s) — exact search found nothing; broadened to: " + displayQuery
261 |                     + "  (Tip: try fewer, more specific keywords)"
262 |                     + "\n<ctrl-a> highlight quote <ctrl-c> copy quote (Right Mouse)";
263 |             } else {
264 |                 summary = "Local corpus returned " + quotes.size()
265 |                     + " passage(s) — searched: " + displayQuery
266 |                     + "\n<ctrl-a> highlight quote <ctrl-c> copy quote (Right Mouse also)";
267 |             }
268 |             return new ResearchReport(summary, quotes);
269 |         } catch (IllegalStateException exception) {
270 |             return new ResearchReport(appConfig.noResultsText(), List.of());
271 |         }
272 |     }
