292 |     private static List<CorpusSearchHit> pickFinalQuotesWithRerank(
293 |         String topic,
294 |         List<CorpusSearchHit> candidatePool,
295 |         int requestedQuotes,
296 |         GeminiClient geminiClient,
297 |         AppConfig appConfig
298 |     ) {
299 |         if (candidatePool.isEmpty()) {
300 |             return List.of();
301 |         }
302 | 
303 |         List<CorpusSearchHit> boundedPool = candidatePool.stream().limit(Math.max(20, requestedQuotes * 6)).toList();
304 |         List<Integer> selectedIds =
305 |             geminiClient.rerankLocalCandidates(topic, boundedPool, requestedQuotes, appConfig);
306 | 
307 |         if (selectedIds.isEmpty()) {
308 |             return boundedPool.stream().limit(requestedQuotes).toList();
309 |         }
310 | 
311 |         List<CorpusSearchHit> selected = new ArrayList<>();
312 |         for (Integer id : selectedIds) {
313 |             int index = id - 1;
314 |             if (index >= 0 && index < boundedPool.size()) {
315 |                 selected.add(boundedPool.get(index));
316 |             }
317 |         }
318 | 
319 |         if (selected.isEmpty()) {
320 |             return boundedPool.stream().limit(requestedQuotes).toList();
321 |         }
322 | 
323 |         if (selected.size() < requestedQuotes) {
324 |             Set<String> selectedKeys = new HashSet<>();
325 |             for (CorpusSearchHit hit : selected) {
326 |                 selectedKeys.add(normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl()));
327 |             }
328 | 
329 |             for (CorpusSearchHit hit : boundedPool) {
330 |                 if (selected.size() >= requestedQuotes) {
331 |                     break;
332 |                 }
333 |                 String key = normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl());
334 |                 if (selectedKeys.add(key)) {
335 |                     selected.add(hit);
336 |                 }
337 |             }
338 |         }
339 | 
340 |         return selected.stream().limit(requestedQuotes).toList();
341 |     }
