364 |     private static List<CorpusSearchHit> rankForDisplay(List<CorpusSearchHit> hits, String requiredAuthor) {
365 |         return hits.stream()
366 |             .sorted((left, right) -> {
367 |                 // Phrase hits (score <= -99990) always sort first — explicit LIKE matches.
368 |                 boolean leftIsPhrase  = left.score()  <= -99990;
369 |                 boolean rightIsPhrase = right.score() <= -99990;
370 |                 if (leftIsPhrase != rightIsPhrase) {
371 |                     return leftIsPhrase ? -1 : 1;
372 |                 }
373 |                 // Among multiple phrase hits, prefer shorter passages. A short passage where
374 |                 // the query covers most of the text is a more precise match than a long passage
375 |                 // that incidentally contains the query words in sequence.
376 |                 if (leftIsPhrase) {
377 |                     int leftLen  = left.quote()  == null ? 0 : left.quote().length();
378 |                     int rightLen = right.quote() == null ? 0 : right.quote().length();
379 |                     return Integer.compare(leftLen, rightLen);
380 |                 }
381 | 
382 |                 int leftSourcePriority = sourcePriority(left, requiredAuthor);
383 |                 int rightSourcePriority = sourcePriority(right, requiredAuthor);
384 |                 if (leftSourcePriority != rightSourcePriority) {
385 |                     return Integer.compare(leftSourcePriority, rightSourcePriority);
386 |                 }
387 | 
388 |                 return Double.compare(left.score(), right.score());
389 |             })
390 |             .toList();
391 |     }
392 | 
393 |     private static int sourcePriority(CorpusSearchHit hit, String requiredAuthor) {
394 |         String normalizedAuthor = normalizeForMatch(requiredAuthor);
395 |         String normalizedTitle = normalizeForMatch(hit.title());
396 |         String normalizedUrl = normalizeForMatch(hit.sourceUrl());
397 | 
398 |         if (!"universal house of justice".equals(normalizedAuthor)) {
399 |             return 1;
400 |         }
401 | 
402 |         if (normalizedUrl.contains("the universal house of justice messages")
403 |             || normalizedUrl.contains("the universal house of justice muhj")
404 |             || normalizedTitle.contains("messages from the universal house of justice")) {
405 |             return 0;
406 |         }
407 | 
408 |         if (normalizedUrl.contains("authoritative texts compilations")
409 |             || normalizedUrl.contains("other literature")
410 |             || normalizedUrl.contains("official statements commentaries")) {
411 |             return 3;
412 |         }
413 | 
414 |         return 1;
415 |     }
