463 |     private static String buildHitsSql(boolean authorScoped, boolean titleScoped) {
464 |         String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
465 |         String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
466 |         return """
467 |             SELECT
468 |                 p.text_content,
469 |                 d.author,
470 |                 d.title,
471 |                 p.locator,
472 |                 d.canonical_url,
473 |                 bm25(passages_fts) AS score
474 |             FROM passages_fts
475 |             JOIN passages p ON p.passage_id = passages_fts.rowid
476 |             JOIN documents d ON d.doc_id = p.doc_id
477 |             WHERE passages_fts MATCH ?
478 |             """ + authorClause + titleClause + """
479 |             ORDER BY score
480 |             LIMIT ?
481 |             """;
482 |     }
483 | 
484 |     private static String buildPhraseSql(boolean authorScoped, boolean titleScoped) {
485 |         String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
486 |         String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
487 |         return """
488 |             SELECT
489 |                 p.text_content,
490 |                 d.author,
491 |                 d.title,
492 |                 p.locator,
493 |                 d.canonical_url,
494 |                 -99999.0 AS score
495 |             FROM passages p
496 |             JOIN documents d ON d.doc_id = p.doc_id
497 |             WHERE lower(p.text_content) LIKE ?
498 |             """ + authorClause + titleClause + """
499 |             LIMIT ?
500 |             """;
501 |     }
502 | 
503 |     private static String buildBookScopedSql(boolean authorScoped, boolean titleScoped) {
504 |         String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
505 |         String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
506 |         return "SELECT\n"
507 |             + "    p.text_content,\n"
508 |             + "    d.author,\n"
509 |             + "    d.title,\n"
510 |             + "    p.locator,\n"
511 |             + "    d.canonical_url,\n"
512 |             + "    -99998.0 AS score\n"
513 |             + "FROM passages p\n"
514 |             + "JOIN documents d ON d.doc_id = p.doc_id\n"
515 |             + "WHERE 1=1\n"
516 |             + authorClause + titleClause
517 |             + "LIMIT ?\n";
518 |     }
