521 |     // Core search — findHits with NEAR/AND/OR fallback
522 |     // -------------------------------------------------------------------------
523 | 
524 |     private static HitsResult findHits(
525 |         CorpusPaths corpusPaths,
526 |         String nearQuery,
527 |         String ftsQuery,
528 |         String orFtsQuery,
529 |         int limit,
530 |         String requiredAuthor,
531 |         String explicitTitle,
532 |         List<String> requestedBookTokens,
533 |         AppConfig appConfig
534 |     ) {
535 |         boolean authorScoped = requiredAuthor != null && !requiredAuthor.isBlank();
536 |         boolean titleScoped  = explicitTitle  != null && !explicitTitle.isBlank();
537 |         String sql = buildHitsSql(authorScoped, titleScoped);
538 | 
539 |         SQLException lastException = null;
540 |         for (int attempt = 1; attempt <= 3; attempt++) {
541 |             try (Connection connection = CorpusConnectionFactory.open(corpusPaths)) {
542 |                 List<CorpusSearchHit> hits = List.of();
543 |                 boolean usedOrFallback = false;
544 |                 String effectiveQuery = ftsQuery;
545 |                 boolean nearAttempted = false;
546 | 
547 |                 if (nearQuery != null && !nearQuery.isBlank()) {
548 |                     nearAttempted = true;
549 | 
550 |                     // 1) Run NEAR query (proximity — exacting)
551 |                     logCount(appConfig, "FtsQuery NEAR: " + nearQuery + " →", 0);
552 |                     List<CorpusSearchHit> nearHits = executeHitsQuery(connection, sql, nearQuery,
553 |                         authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
554 |                     logCount(appConfig, "NEAR hits", nearHits.size());
555 | 
556 |                     // 2) Run AND query to supplement — NEAR can be thin
557 |                     logCount(appConfig, "FtsQuery AND (supplement): " + ftsQuery + " →", 0);
558 |                     List<CorpusSearchHit> andHits = executeHitsQuery(connection, sql, ftsQuery,
559 |                         authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
560 |                     logCount(appConfig, "AND supplement hits", andHits.size());
561 | 
562 |                     // 3) Boost NEAR scores so proximity matches rank above AND hits
563 |                     if (!nearHits.isEmpty()) {
564 |                         nearHits = applyNearBoost(nearHits);
565 |                     }
566 | 
567 |                     // 4) Merge: NEAR first (boosted), then AND (deduplicated)
568 |                     hits = mergeHits(nearHits, andHits);
569 | 
570 |                     if (!nearHits.isEmpty()) {
571 |                         effectiveQuery = nearQuery;
572 |                     } else if (!andHits.isEmpty()) {
573 |                         effectiveQuery = ftsQuery;
574 |                     }
575 |                 }
576 | 
577 |                 if (!nearAttempted) {
578 |                     logCount(appConfig, "FtsQuery AND: " + ftsQuery + " →", 0);
579 |                     hits = executeHitsQuery(connection, sql, ftsQuery,
580 |                         authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
581 |                     logCount(appConfig, "AND hits", hits.size());
582 | 
583 |                     if (hits.isEmpty() && !orFtsQuery.isBlank() && !orFtsQuery.equals(ftsQuery)) {
584 |                         logCount(appConfig, "FtsQuery OR: " + orFtsQuery + " →", 0);
585 |                         hits = executeHitsQuery(connection, sql, orFtsQuery,
586 |                             authorScoped, requiredAuthor, titleScoped, explicitTitle, limit);
587 |                         logCount(appConfig, "OR hits", hits.size());
588 |                         usedOrFallback = true;
589 |                         effectiveQuery = orFtsQuery;
590 |                     }
591 |                 }
592 | 
593 |                 // Note: book filter not applied here — it runs in search() after author/content filtering.
594 |                 // Keeping it here would be redundant and would double-filter.
595 | 
596 |                 List<CorpusSearchHit> limited = hits.stream()
597 |                     .limit(Math.max(1, limit))
598 |                     .toList();
599 |                 return new HitsResult(limited, effectiveQuery, usedOrFallback);
600 |             } catch (SQLException exception) {
601 |                 lastException = exception;
602 |                 if (!isBusyLock(exception) || attempt == 3) {
603 |                     break;
604 |                 }
605 | 
606 |                 try {
607 |                     Thread.sleep(200L * attempt);
608 |                 } catch (InterruptedException interruptedException) {
609 |                     Thread.currentThread().interrupt();
610 |                     throw new IllegalStateException("Local corpus query was interrupted.", interruptedException);
611 |                 }
612 |             }
613 |         }
614 | 
615 |         throw new IllegalStateException("Local corpus query failed.", lastException);
616 |     }
617 | 
618 |     /** Multiplies each hit's BM25 score so NEAR proximity results rank above AND/OR hits. */
619 |     private static List<CorpusSearchHit> applyNearBoost(List<CorpusSearchHit> hits) {
620 |         return hits.stream()
621 |             .map(hit -> new CorpusSearchHit(
622 |                 hit.quote(), hit.author(), hit.title(),
623 |                 hit.locator(), hit.sourceUrl(),
624 |                 hit.score() * NEAR_BOOST_MULTIPLIER))
625 |             .toList();
626 |     }
