778 |     private static List<CorpusSearchHit> mergeHits(List<CorpusSearchHit> primary, List<CorpusSearchHit> secondary) {
779 |         List<CorpusSearchHit> merged = new ArrayList<>(primary);
780 |         Set<String> seen = new HashSet<>();
781 |         for (CorpusSearchHit hit : primary) {
782 |             seen.add(normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl()));
783 |         }
784 | 
785 |         for (CorpusSearchHit hit : secondary) {
786 |             String key = normalizeForMatch(hit.quote()) + "|" + normalizeForMatch(hit.sourceUrl());
787 |             if (seen.add(key)) {
788 |                 merged.add(hit);
789 |             }
790 |         }
791 |         return merged;
792 |     }
