package com.bahairesearch.corpus;

import com.bahairesearch.ai.GeminiClient;
import com.bahairesearch.config.AppConfig;
import com.bahairesearch.common.model.CorpusSearchHit;
import com.bahairesearch.common.model.QuoteResult;
import com.bahairesearch.common.model.ResearchReport;
import com.bahairesearch.common.search.SearchCore;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.logging.Logger;

/**
 * Executes local full-text search and maps verified local passages to report output.
 * <p>Query building, tokenization, filtering, ranking, and deduplication logic is
 * delegated to {@link SearchCore} from the shared bahai-search-common library.</p>
 */
public final class LocalCorpusSearchService {

    private static final Logger LOGGER = Logger.getLogger(LocalCorpusSearchService.class.getName());

    private record HitsResult(List<CorpusSearchHit> hits, String effectiveQuery, boolean usedFallback) {}

    private LocalCorpusSearchService() {
    }

    /**
     * Search local corpus and return a report with local citations only.
     */
    public static ResearchReport search(String topic, AppConfig appConfig) {
        return search(topic, null, null, appConfig);
    }

    /**
     * Search local corpus with optional explicit author/title filters from UI dropdowns.
     *
     * @param explicitAuthor exact canonical author value (e.g. "Baha'u'llah"), or null for inference
     * @param explicitTitle  exact title string from dropdown, or null for no title filter
     */
    public static ResearchReport search(
        String topic,
        String explicitAuthor,
        String explicitTitle,
        AppConfig appConfig
    ) {
        try {
            CorpusPaths corpusPaths = CorpusPaths.fromConfig(appConfig);

            // Determine author early so FTS query can exclude author tokens
            boolean hasExplicitAuthor = explicitAuthor != null && !explicitAuthor.isBlank();
            String manualRequiredAuthor = hasExplicitAuthor ? explicitAuthor : inferRequiredAuthor(topic);

            String nearQuery = SearchCore.toFtsQueryNear(topic, manualRequiredAuthor);
            String ftsQuery = SearchCore.toFtsQuery(topic, manualRequiredAuthor);
            String orFtsQuery = SearchCore.toFtsQueryOr(topic, manualRequiredAuthor);
            if (ftsQuery.isBlank()) {
                return new ResearchReport(appConfig.noResultsText(), List.of());
            }

            List<String> knownWorkTitles = loadKnownWorkTitles(corpusPaths);
            GeminiClient geminiClient = new GeminiClient(appConfig);
            GeminiClient.LocalQueryIntent intent =
                geminiClient.resolveLocalQueryIntent(topic, knownWorkTitles, appConfig);

            int requestedQuotes = Math.max(1, appConfig.maxQuotes());
            int retrievalPoolSize = Math.max(requestedQuotes * 12, 60);

            // Author priority: explicit UI selection > manual topic inference only.
            // AI-inferred author is suppressed — it causes false restrictions when
            // "All Authors" is selected but the topic themes suggest one author.
            String requiredAuthor = manualRequiredAuthor;

            // When the user explicitly selected an author but left Title as "All Titles"
            // (explicitTitle == null), suppress AI work-title inference. The user's intent
            // is to search all of that author's works — the AI must not narrow it to one book
            // just because a search word happens to appear in a title (e.g. "unity" → Tabernacle of Unity).
            boolean suppressAiWorkTitle = hasExplicitAuthor && explicitTitle == null;
            String requestedBookTitle = suppressAiWorkTitle ? null : (explicitTitle != null ? explicitTitle : intent.workTitle());
            List<String> requestedBookTokens = SearchCore.bookTokensFromTitle(requestedBookTitle);

            // Concept terms from AI (for post-retrieval content-term filtering)
            // Use AI-inferred concepts when available, otherwise fall back to extracted content terms
            List<String> conceptTerms = (intent.concepts() != null && !intent.concepts().isEmpty())
                ? intent.concepts()
                : SearchCore.extractContentTerms(topic, requiredAuthor);

            logIntentDebug(appConfig, topic, ftsQuery, intent, requiredAuthor, requestedBookTokens, conceptTerms);

            // ── Strategy 1: Near-proximity FTS5 query ─────────────────────
            HitsResult nearResult = searchHitsDriver(
                corpusPaths, nearQuery, requiredAuthor, requestedBookTokens,
                conceptTerms, retrievalPoolSize, false);
            List<CorpusSearchHit> allHits = new ArrayList<>(nearResult.hits());

            // ── Strategy 2: AND query (if NEAR returned too few) ──────────
            boolean needAnd = allHits.size() < retrievalPoolSize;
            if (needAnd && !ftsQuery.isEmpty()) {
                HitsResult andResult = searchHitsDriver(
                    corpusPaths, ftsQuery, requiredAuthor, requestedBookTokens,
                    conceptTerms, retrievalPoolSize - allHits.size(), false);
                allHits = SearchCore.mergeHits(allHits, andResult.hits());
            }

            // ── Strategy 3: OR fallback (if both above returned too few) ───
            boolean needOr = allHits.size() < retrievalPoolSize;
            if (needOr && !orFtsQuery.isEmpty()) {
                HitsResult orResult = searchHitsDriver(
                    corpusPaths, orFtsQuery, requiredAuthor, requestedBookTokens,
                    conceptTerms, retrievalPoolSize - allHits.size(), true);
                allHits = SearchCore.mergeHits(allHits, orResult.hits());
            }

            // ── Strategy 4: Phrase/LIKE fallback (if everything above fails) ──
            boolean needPhraseLike = allHits.stream().noneMatch(h -> h.score() > SearchCore.PHRASE_SCORE_THRESHOLD);
            if (needPhraseLike) {
                // Use content terms only (no FTS) — try each term independently
                List<String> contentTerms = SearchCore.extractContentTerms(topic, requiredAuthor);
                if (!contentTerms.isEmpty()) {
                    HitsResult phraseResult = searchByPhraseLike(
                        corpusPaths, requiredAuthor, requestedBookTokens,
                        conceptTerms, contentTerms, retrievalPoolSize);
                    allHits = SearchCore.mergeHits(allHits, phraseResult.hits());
                }
            }

            logCount(appConfig, "allHits(pre-dedup)", allHits.size());

            // ── Ranking and deduplication ────────────────────────────────────
            allHits = SearchCore.removeBoilerplateAndDuplicates(allHits);
            allHits = SearchCore.rankForDisplay(allHits);

            logCount(appConfig, "allHits(post-dedup)", allHits.size());

            // ── AI re-ranking (top candidates only) ──────────────────────────
            List<CorpusSearchHit> finalHits;
            List<CorpusSearchHit> candidatesForAi = allHits.size() > 90 ? allHits.subList(0, 90) : allHits;
            List<Integer> selectedIds = geminiClient.rerankLocalCandidates(
                topic, candidatesForAi, requestedQuotes, appConfig);
            if (!selectedIds.isEmpty()) {
                finalHits = new ArrayList<>();
                for (int id : selectedIds) {
                    finalHits.add(candidatesForAi.get(id - 1));
                }
            } else {
                // AI re-ranking returned empty — fall back to top-N by score
                int limit = Math.min(requestedQuotes, allHits.size());
                finalHits = allHits.subList(0, limit);
            }

            logCount(appConfig, "finalHits", finalHits.size());

            // ── Build report ─────────────────────────────────────────────────
            if (finalHits.isEmpty()) {
                return new ResearchReport(appConfig.noResultsText(), List.of());
            }

            List<QuoteResult> quotes = new ArrayList<>();
            for (CorpusSearchHit hit : finalHits) {
                quotes.add(new QuoteResult(
                    hit.quote(),
                    hit.author(),
                    hit.title(),
                    hit.locator(),
                    hit.sourceUrl()
                ));
            }

            String summary = "Based on the local corpus, here are the most relevant passages found for \""
                + topic + "\".";
            return new ResearchReport(summary, quotes);
        } catch (Exception e) {
            String logMessage = e.getMessage() == null ? e.getClass().getSimpleName() : e.getMessage();
            LOGGER.warning(() -> "LocalCorpusSearchService.search failed: " + logMessage);
            return new ResearchReport(appConfig.noResultsText(), List.of());
        }
    }

    // -------------------------------------------------------------------------
    // Search drivers — database access
    // -------------------------------------------------------------------------

    private static HitsResult searchHitsDriver(
        CorpusPaths corpusPaths,
        String query,
        String requiredAuthor,
        List<String> requestedBookTokens,
        List<String> conceptTerms,
        int maxResults,
        boolean isOrFallback
    ) {
        if (query == null || query.isBlank()) {
            return new HitsResult(List.of(), "", false);
        }

        int totalMaxRows = maxResults + 200; // buffer for post-filter dedup loss
        String effectiveQuery = query;

        String sql;
        if (isOrFallback) {
            sql = "SELECT content, author, title, locator, source_url, rank "
                + "FROM passages "
                + "WHERE passages MATCH ? "
                + (requiredAuthor != null ? "AND lower(author) = lower(?) " : "")
                + "ORDER BY rank ASC "
                + "LIMIT ?";
        } else {
            sql = "SELECT content, author, title, locator, source_url, bm25(passages, 0.0, 80.0, 10.0, 10.0, 5.0) AS bm25_score "
                + "FROM passages "
                + "WHERE passages MATCH ? "
                + (requiredAuthor != null ? "AND lower(author) = lower(?) " : "")
                + "ORDER BY bm25_score ASC "
                + "LIMIT ?";
        }

        try (Connection connection = CorpusConnectionFactory.open(corpusPaths);
             PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setString(1, query);
            if (requiredAuthor != null) {
                stmt.setString(2, requiredAuthor);
                stmt.setInt(3, totalMaxRows);
            } else {
                stmt.setInt(2, totalMaxRows);
            }

            List<CorpusSearchHit> hits = new ArrayList<>();
            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    String content = rs.getString(1);
                    String author = rs.getString(2);
                    String title = rs.getString(3);
                    String locator = rs.getString(4);
                    String sourceUrl = rs.getString(5);
                    double score;
                    if (isOrFallback) {
                        score = rs.getDouble(6);
                    } else {
                        score = rs.getDouble(6);
                    }

                    if (content == null || content.trim().isEmpty()) continue;

                    hits.add(new CorpusSearchHit(
                        content.trim(),
                        blankToFallback(author, ""),
                        blankToFallback(title, ""),
                        blankToFallback(locator, ""),
                        blankToFallback(sourceUrl, ""),
                        score
                    ));
                }
            }

            // Post-retrieval author filter (double-check)
            hits = SearchCore.filterByRequestedAuthor(requiredAuthor, hits);
            // Post-retrieval book filter
            hits = SearchCore.filterByRequestedBook(hits, requestedBookTokens);
            // Post-retrieval content term filter
            if (!isOrFallback) {
                hits = SearchCore.filterByContentTerms(hits, conceptTerms);
            } else {
                // OR fallback: more lenient — at least one concept term in result set
                if (!conceptTerms.isEmpty()) {
                    hits = SearchCore.filterByContentTerms(hits, conceptTerms);
                }
            }

            // Apply NEAR boost if the query was a NEAR query
            if (effectiveQuery.startsWith("NEAR(")) {
                hits = SearchCore.applyNearBoost(hits);
            }

            int limitedSize = Math.min(hits.size(), maxResults);
            return new HitsResult(hits.subList(0, limitedSize), query, isOrFallback);
        } catch (SQLException e) {
            LOGGER.warning(() -> "FTS query failed: \"" + query + "\": " + e.getMessage());
            return new HitsResult(List.of(), query, isOrFallback);
        }
    }

    /**
     * Phrase/LIKE fallback search — executed only when AND/NEAR/OR FTS queries
     * returned zero results. Uses SQL LIKE on each content term independently,
     * then merges results into a single ranked list.
     */
    private static HitsResult searchByPhraseLike(
        CorpusPaths corpusPaths,
        String requiredAuthor,
        List<String> requestedBookTokens,
        List<String> conceptTerms,
        List<String> contentTerms,
        int maxResults
    ) {
        // Collect the longest 3 content terms for LIKE pattern
        List<String> sortedTerms = new ArrayList<>(contentTerms);
        sortedTerms.sort((a, b) -> Integer.compare(b.length(), a.length()));
        List<String> topTerms = sortedTerms.size() > 3 ? sortedTerms.subList(0, 3) : sortedTerms;

        List<CorpusSearchHit> merged = new ArrayList<>();
        Set<String> seenKeys = new HashSet<>();

        int remaining = maxResults;
        for (String term : topTerms) {
            if (remaining <= 0) break;

            String likePattern = "%" + term + "%";
            String sql = "SELECT content, author, title, locator, source_url, length(content) AS char_count "
                + "FROM passages "
                + "WHERE content LIKE ? "
                + (requiredAuthor != null ? "AND lower(author) = lower(?) " : "")
                + "ORDER BY char_count ASC "
                + "LIMIT ?";

            try (Connection connection = CorpusConnectionFactory.open(corpusPaths);
                 PreparedStatement stmt = connection.prepareStatement(sql)) {
                stmt.setString(1, likePattern);
                if (requiredAuthor != null) {
                    stmt.setString(2, requiredAuthor);
                    stmt.setInt(3, remaining + 30);
                } else {
                    stmt.setInt(2, remaining + 30);
                }

                try (ResultSet rs = stmt.executeQuery()) {
                    while (rs.next() && remaining > 0) {
                        String content = rs.getString(1);
                        String author = rs.getString(2);
                        String title = rs.getString(3);
                        String locator = rs.getString(4);
                        String sourceUrl = rs.getString(5);

                        if (content == null || content.trim().isEmpty()) continue;

                        String key = SearchCore.normalizeForMatch(content) + "|" + SearchCore.normalizeForMatch(sourceUrl);
                        if (!seenKeys.add(key)) continue;

                        // Use negative length as score so shorter = ranked higher
                        double phraseScore = SearchCore.PHRASE_SCORE_THRESHOLD - (double) rs.getInt(6);

                        CorpusSearchHit hit = new CorpusSearchHit(
                            content.trim(),
                            blankToFallback(author, ""),
                            blankToFallback(title, ""),
                            blankToFallback(locator, ""),
                            blankToFallback(sourceUrl, ""),
                            phraseScore
                        );

                        // Apply book filter if needed
                        if (!requestedBookTokens.isEmpty()
                            && SearchCore.countBookTokenMatches(hit, requestedBookTokens) < 2) {
                            continue;
                        }

                        merged.add(hit);
                        remaining--;
                    }
                }
            } catch (SQLException e) {
                LOGGER.warning(() -> "LIKE phrase query failed for term \"" + term + "\": " + e.getMessage());
            }
        }

        return new HitsResult(merged, "phrase-like:" + String.join(" ", topTerms), true);
    }

    // -------------------------------------------------------------------------
    // Book title loading
    // -------------------------------------------------------------------------

    private static List<String> loadKnownWorkTitles(CorpusPaths corpusPaths) {
        String sql = "SELECT DISTINCT title FROM documents WHERE title IS NOT NULL AND trim(title) != '' ORDER BY title";
        List<String> titles = new ArrayList<>();
        try (Connection connection = CorpusConnectionFactory.open(corpusPaths);
             PreparedStatement stmt = connection.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {
            while (rs.next()) {
                String title = rs.getString(1);
                if (title != null && !title.isBlank()) {
                    titles.add(title.trim());
                }
            }
        } catch (SQLException e) {
            LOGGER.warning(() -> "Failed to load known work titles: " + e.getMessage());
        }
        return titles;
    }

    // -------------------------------------------------------------------------
    // Author inference — still local; SearchCore has no Baha'i-author knowledge
    // -------------------------------------------------------------------------

    /**
     * Infer required author from the raw topic text.
     * Returns exact values as stored in the DB from manifest.csv (e.g. "Baha'u'llah", not "bah").
     */
    private static String inferRequiredAuthor(String topic) {
        String normalized = SearchCore.normalizeForMatch(topic);
        // Pad so word-boundary checks work for single tokens at start/end
        String padded = " " + normalized + " ";

        if (padded.contains(" universal house of justice ")
                || padded.contains(" house of justice ")
                || padded.contains(" uhj ")) {
            return "Universal House of Justice";
        }
        // Check Baha'u'llah before "bab" to avoid false partial matches
        if (padded.contains(" baha u llah ") || padded.contains(" bahaullah ")) {
            return "Baha'u'llah";
        }
        if (padded.contains(" abdu l baha ") || padded.contains(" abdu baha ")) {
            return "'Abdu'l-Baha";
        }
        if (padded.contains(" shoghi effendi ")) {
            return "Shoghi Effendi";
        }
        // "bab" checked last — whole-word only via padded boundaries
        if (padded.contains(" bab ")) {
            return "Bab";
        }
        return null;
    }

