133 |             List<CorpusSearchHit> hits = hitsResult.hits();
134 |             logCount(appConfig, "hits", hits.size());
135 | 
136 |             List<CorpusSearchHit> filtered = filterByRequestedAuthor(requiredAuthor, hits);
137 |             List<CorpusSearchHit> bookScoped = filterByRequestedBook(filtered, requestedBookTokens);
138 |             List<CorpusSearchHit> topical = filterByContentTerms(bookScoped, conceptTerms);
139 | 
140 |             // Phrase searches — always run, independent of AI/API key.
141 |             // Phrase hits use score=-99999 so they sort before qualityBand ordering and are
142 |             // never displaced by longer passages in rankForDisplay.
143 |             // IMPORTANT: phrase hits are merged FIRST so their score survives deduplication.
144 |             // If HW #5 (short passage) appears in both FTS results and phrase results,
145 |             // mergeHits keeps the first-seen version — we want the phrase version (-99999),
146 |             // not the FTS version (BM25 ~-5) which would be buried behind band-0 passages.
147 |             // Only phrase-search when topic has 2+ significant words — a single word adds
148 |             // no precision over FTS and just duplicates the same 144+ hits.
149 |             List<String> topicFtsTokens = extractFtsTokens(topic, requiredAuthor);
150 |             boolean nearFired = hitsResult.effectiveQuery().startsWith("NEAR(");
151 |             String topicLikePattern = "%" + normalizeForMatch(topic).replace(" ", "%") + "%";
152 |             List<CorpusSearchHit> combinedPhraseHits = new ArrayList<>();
153 |             if (topicFtsTokens.size() >= 2 && !nearFired) {
154 |                 logCount(appConfig, "PhraseQuery topic LIKE: " + topicLikePattern + " →", 0);
155 |                 combinedPhraseHits.addAll(fetchPhraseHits(
156 |                     corpusPaths, topic, retrievalPoolSize,
157 |                     requiredAuthor, explicitTitle, requestedBookTokens));
158 |                 logCount(appConfig, "PhraseQuery topic hits", combinedPhraseHits.size());
159 |             }
160 |             if (intent.knownPhrase() != null && !intent.knownPhrase().isBlank() && !nearFired) {
161 |                 String aiLikePattern = "%" + normalizeForMatch(intent.knownPhrase()).replace(" ", "%") + "%";
162 |                 logCount(appConfig, "PhraseQuery AI LIKE: " + aiLikePattern + " →", 0);
163 |                 List<CorpusSearchHit> aiPhraseHits = fetchPhraseHits(
164 |                     corpusPaths, intent.knownPhrase(), retrievalPoolSize,
165 |                     requiredAuthor, explicitTitle, requestedBookTokens);
166 |                 logCount(appConfig, "PhraseQuery AI hits", aiPhraseHits.size());
167 |                 combinedPhraseHits = mergeHits(combinedPhraseHits, aiPhraseHits);
168 |             }
169 |             // Phrase hits first, then FTS hits fill in non-duplicates
170 |             topical = mergeHits(combinedPhraseHits, topical);
171 |             logCount(appConfig, "after phrase merge", topical.size());
172 | 
173 |             if (!requestedBookTokens.isEmpty() && topical.size() < requestedQuotes && !nearFired) {
174 |                 List<CorpusSearchHit> additionalBookScopedHits = findAdditionalBookScopedHits(
175 |                     corpusPaths,
176 |                     requiredAuthor,
177 |                     explicitTitle,
178 |                     requestedBookTokens,
179 |                     conceptTerms,
180 |                     Math.max(240, requestedQuotes * 50)
181 |                 );
182 |                 topical = mergeHits(topical, additionalBookScopedHits);
183 |             }
184 | 
185 |             List<CorpusSearchHit> candidatePool =
186 |                 rankForDisplay(removeBoilerplateAndDuplicates(topical), requiredAuthor);
187 |             logCount(appConfig, "candidatePool (main pipeline)", candidatePool.size());
188 | 
189 |             // Semantic fallback: triggered when the full pipeline yields no candidates.
190 |             // Two scenarios this catches:
191 |             //   (a) Raw-text FTS finds nothing — e.g. query mentions "Allie Beth Stuckey" which
192 |             //       is never in scripture, OR modern words like "empathy" not in the corpus.
193 |             //   (b) OR FTS found hits but they were all eliminated by content/book filters.
194 |             // Retries using AI-extracted concepts ("love", "compassion") as FTS terms instead
195 |             // of raw text, and uses AI-only conceptTerms so paragraph noise words can't filter out
196 |             // relevant passages. Book tokens intentionally omitted — if AI guessed a wrong title
197 |             // it should not carry forward into the fallback.
198 |             if (candidatePool.isEmpty() && intent.concepts() != null && !intent.concepts().isEmpty()) {
199 |                 String conceptQuery = String.join(" ", intent.concepts());
200 |                 String conceptOrFtsQuery = toFtsQueryOr(conceptQuery, requiredAuthor);
201 |                 // Use the OR concept query directly — semantic fallback is last-resort mode.
202 |                 // AND concept queries (e.g. "love* AND empathy* AND unity*") find only 1-2 narrow
203 |                 // passages and miss the OR fallback inside findHits because hits.isEmpty() is false.
204 |                 // Those 1-2 passages are often boilerplate-filtered, leaving candidatePool empty.
205 |                 // Going straight to OR ("love* OR unity* OR compassion*") retrieves a broad pool
206 |                 // of the most BM25-relevant passages on these themes across the full corpus,
207 |                 // with room for the Gemini reranker to pick the best for the specific question.
208 |                 if (!conceptOrFtsQuery.isBlank() && !conceptOrFtsQuery.equals(orFtsQuery)) {
209 |                     List<CorpusSearchHit> conceptHits = findHits(
210 |                         corpusPaths, "", conceptOrFtsQuery, conceptOrFtsQuery,
211 |                         retrievalPoolSize, requiredAuthor, explicitTitle,
212 |                         List.of(), appConfig
213 |                     ).hits();
214 |                     logCount(appConfig, "semantic fallback conceptHits", conceptHits.size());
215 |                     if (!conceptHits.isEmpty()) {
216 |                         List<String> aiOnlyTerms = inferEffectiveConceptTerms("", requiredAuthor, intent.concepts());
217 |                         List<CorpusSearchHit> conceptFiltered = filterByRequestedAuthor(requiredAuthor, conceptHits);
218 |                         // Do NOT apply filterByContentTerms here — the concept FTS already ensures
219 |                         // topical relevance. Exact-token filtering causes false negatives when FTS
220 |                         // prefix (e.g. "love*") matched inflected forms ("beloved", "loveth") that
221 |                         // fail exact-word comparison. The Gemini reranker handles final selection.
222 |                         candidatePool = rankForDisplay(removeBoilerplateAndDuplicates(conceptFiltered), requiredAuthor);
223 |                         logCount(appConfig, "candidatePool (semantic fallback)", candidatePool.size());
224 |                         logIntentDebug(appConfig, topic,
225 |                             "SEMANTIC-FALLBACK:" + conceptOrFtsQuery, intent,
226 |                             requiredAuthor, List.of(), aiOnlyTerms);
227 |                     }
228 |                 }
229 |             }
230 | 
231 |             List<CorpusSearchHit> curated = pickFinalQuotesWithRerank(
232 |                 topic,
233 |                 candidatePool,
234 |                 requestedQuotes,
235 |                 geminiClient,
236 |                 appConfig
237 |             );
238 |             if (curated.isEmpty()) {
239 |                 return new ResearchReport(appConfig.noResultsText(), List.of());
240 |             }
241 | 
242 |             List<QuoteResult> quotes = curated.stream()
243 |                 .map(hit -> new QuoteResult(
244 |                     hit.quote(),
245 |                     blankToFallback(hit.author(), "Unknown"),
246 |                     blankToFallback(hit.title(), "Untitled"),
247 |                     blankToFallback(hit.locator(), "Not specified"),
248 |                     blankToFallback(hit.sourceUrl(), "N/A")
249 |                 ))
250 |                 .toList();
251 | 
252 |             String displayQuery = hitsResult.effectiveQuery()
253 |                 .replaceAll("NEAR\\(([^,]+),\\s*\\d+\\)", "$1")
254 |                 .replace("*", "")
255 |                 .replace(" AND ", " and ")
256 |                 .replace(" OR ", " or ");
257 |             String summary;
258 |             if (hitsResult.usedFallback()) {
259 |                 summary = "Local corpus returned " + quotes.size()
260 |                     + " passage(s) — exact search found nothing; broadened to: " + displayQuery
261 |                     + "  (Tip: try fewer, more specific keywords)"
262 |                     + "\n<ctrl-a> highlight quote <ctrl-c> copy quote (Right Mouse)";
263 |             } else {
264 |                 summary = "Local corpus returned " + quotes.size()
265 |                     + " passage(s) — searched: " + displayQuery
266 |                     + "\n<ctrl-a> highlight quote <ctrl-c> copy quote (Right Mouse also)";
267 |             }
268 |             return new ResearchReport(summary, quotes);
269 |         } catch (IllegalStateException exception) {
270 |             return new ResearchReport(appConfig.noResultsText(), List.of());
271 |         }
272 |     }
