275 |         String sql = "SELECT DISTINCT title FROM documents WHERE title IS NOT NULL AND trim(title) <> ''";
276 |         List<String> titles = new ArrayList<>();
277 |         try (Connection connection = CorpusConnectionFactory.open(corpusPaths);
278 |              PreparedStatement statement = connection.prepareStatement(sql);
279 |              ResultSet resultSet = statement.executeQuery()) {
280 |             while (resultSet.next()) {
281 |                 String title = trimToEmpty(resultSet.getString(1));
282 |                 if (!title.isBlank()) {
283 |                     titles.add(title);
