343 |     private static List<CorpusSearchHit> removeBoilerplateAndDuplicates(List<CorpusSearchHit> hits) {
344 |         List<CorpusSearchHit> curated = new ArrayList<>();
345 |         Set<String> seen = new HashSet<>();
346 |         for (CorpusSearchHit hit : hits) {
347 |             String reason = boilerplateReason(hit);
348 |             if (reason != null) {
349 |                 String snippet = normalizeForMatch(hit.quote());
350 |                 String display = snippet.length() > 120 ? snippet.substring(0, 120) + "..." : snippet;
351 |                 LOGGER.info(() -> "[BoilerplateFilter] removed (" + reason + "): \"" + display + "\"");
352 |                 continue;
353 |             }
354 | 
355 |             String key = normalizeForMatch(hit.quote());
356 |             if (key.isBlank() || !seen.add(key)) {
357 |                 continue;
358 |             }
359 |             curated.add(hit);
360 |         }
361 |         return curated;
362 |     }
