417 |     private static int qualityBand(String quote) {
418 |         int length = quote == null ? 0 : quote.trim().length();
419 |         if (length >= 200 && length <= 900) {
420 |             return 0;
421 |         }
422 |         if (length >= 120 && length <= 1100) {
423 |             return 1;
424 |         }
425 |         return 2;
426 |     }
