428 |     /** Returns a short label identifying which boilerplate check matched, or null if not boilerplate. */
429 |     private static String boilerplateReason(CorpusSearchHit hit) {
430 |         // A passage over 15,000 characters is an entire book ingested as one chunk — not a usable quote.
431 |         // Individual prayers, tablets, and letters are well under this limit even when lengthy.
432 |         if (hit.quote().length() > 15_000) {
433 |             return "too-long";
434 |         }
435 |         String quote = normalizeForMatch(hit.quote());
436 |         if (quote.contains("bahai reference library")) {
437 |             return "bahai-ref-lib";
438 |         }
439 |         if (quote.startsWith("a collection of") || quote.startsWith("a selection of")) {
440 |             return "collection-header";
441 |         }
442 |         if (quote.contains("can be found here")) {
443 |             return "found-here";
444 |         }
445 |         if (quote.contains("downloads about downloads")
446 |             || quote.contains("all downloads in authoritative writings and guidance")
447 |             || quote.contains("copyright and terms of use")
448 |             || quote.contains("read online")
449 |             || quote.contains("bahai org home")
450 |             || quote.contains("search the bahai reference library")) {
451 |             return "nav-element";
452 |         }
453 |         if (quote.contains("see also")) {
454 |             return "see-also";
455 |         }
456 |         return null;
457 |     }
