682 |     private static List<CorpusSearchHit> findKnownPhraseHits(
683 |         Connection connection,
684 |         String knownPhrase,
685 |         int limit,
686 |         String requiredAuthor,
687 |         String explicitTitle,
688 |         List<String> requestedBookTokens
689 |     ) throws SQLException {
690 |         boolean authorScoped = requiredAuthor != null && !requiredAuthor.isBlank();
691 |         boolean titleScoped  = explicitTitle  != null && !explicitTitle.isBlank();
692 |         String sql = buildPhraseSql(authorScoped, titleScoped);
