628 |     private static List<CorpusSearchHit> executeHitsQuery(
629 |         Connection connection,
630 |         String sql,
631 |         String ftsQuery,
632 |         boolean authorScoped,
633 |         String requiredAuthor,
634 |         boolean titleScoped,
635 |         String explicitTitle,
636 |         int limit
637 |     ) throws SQLException {
638 |         List<CorpusSearchHit> hits = new ArrayList<>();
639 |         try (PreparedStatement statement = connection.prepareStatement(sql)) {
640 |             int p = 1;
641 |             statement.setString(p++, ftsQuery);
642 |             if (authorScoped) {
643 |                 statement.setString(p++, requiredAuthor);
644 |             }
645 |             if (titleScoped) {
646 |                 statement.setString(p++, explicitTitle);
647 |             }
648 |             statement.setInt(p, Math.max(1, limit));
649 | 
650 |             try (ResultSet resultSet = statement.executeQuery()) {
651 |                 while (resultSet.next()) {
652 |                     hits.add(new CorpusSearchHit(
653 |                         trimToEmpty(resultSet.getString(1)),
654 |                         trimToEmpty(resultSet.getString(2)),
655 |                         trimToEmpty(resultSet.getString(3)),
656 |                         trimToEmpty(resultSet.getString(4)),
657 |                         trimToEmpty(resultSet.getString(5)),
658 |                         resultSet.getDouble(6)
659 |                     ));
660 |                 }
661 |             }
662 |         }
663 |         return hits;
664 |     }
