666 |     private static List<CorpusSearchHit> fetchPhraseHits(
667 |         CorpusPaths corpusPaths,
668 |         String knownPhrase,
669 |         int limit,
670 |         String requiredAuthor,
671 |         String explicitTitle,
672 |         List<String> requestedBookTokens
673 |     ) {
