                        logCount(appConfig, "candidatePool (semantic fallback)", candidatePool.size());
                        logIntentDebug(appConfig, topic,
                            "SEMANTIC-FALLBACK:" + conceptOrFtsQuery, intent,
                            requiredAuthor, List.of(), aiOnlyTerms);
                    }
                }
            }

