                return new ResearchReport(appConfig.noResultsText(), List.of());
            }

            List<QuoteResult> quotes = curated.stream()
                .map(hit -> new QuoteResult(
                    hit.quote(),
                    SearchCore.blankToFallback(hit.author(), "Unknown"),
