        String authorClause = authorScoped ? "  AND lower(d.author) = lower(?)\n" : "";
        String titleClause  = titleScoped  ? "  AND lower(d.title)  = lower(?)\n" : "";
        return "SELECT\n"
            + "    p.text_content,\n"
            + "    d.author,\n"
            + "    d.title,\n"
            + "    p.locator,\n"
            + "    d.canonical_url,\n"
            + "    -99998.0 AS score\n"
            + "FROM passages p\n"
            + "JOIN documents d ON d.doc_id = p.doc_id\n"
            + "WHERE 1=1\n"
